<template><div class="app-container category-page"><div class="page-head"><div><h2>物品分类</h2><p>维护失物与招领信息使用的分类</p></div><el-button type="primary" icon="el-icon-plus" @click="edit()">新增分类</el-button></div><div class="category-card"><el-table v-loading="loading" :data="items"><el-table-column label="分类" min-width="240"><template slot-scope="{row}"><div class="category-cell"><span><i class="el-icon-collection-tag" /></span><strong>{{row.categoryName}}</strong></div></template></el-table-column><el-table-column prop="sortNo" label="排序值" width="120" align="center" /><el-table-column label="状态" width="120" align="center"><template slot-scope="{row}"><el-tag size="small" :type="row.status===1?'success':'info'">{{row.status===1?'使用中':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150" align="center"><template slot-scope="{row}"><el-button type="text" @click="edit(row)">编辑</el-button><el-button type="text" class="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><pagination :total="total" :current-page.sync="page.current" :page-size.sync="page.size" :page-sizes="[10,20,50]" @pagination="load" /><el-dialog :title="form.id?'编辑分类':'新增分类'" :visible.sync="open" width="460px" append-to-body><el-form ref="form" :model="form" :rules="rules" label-width="80px"><el-form-item label="名称" prop="categoryName"><el-input v-model.trim="form.categoryName" maxlength="30" show-word-limit placeholder="例如：数码产品" /></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0" :max="999" /></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio-button :label="1">启用</el-radio-button><el-radio-button :label="0">停用</el-radio-button></el-radio-group></el-form-item></el-form><div slot="footer"><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></div></el-dialog></div></template>
<script>import Pagination from '@/components/Pagination';import{deleteItemCategory,pageItemCategory,saveItemCategory,updateItemCategory}from'@/api/item_category';export default{name:'ItemCategoryManage',components:{Pagination},data(){return{loading:false,items:[],total:0,page:{current:1,size:10},open:false,form:{},rules:{categoryName:[{required:true,message:'请输入分类名称',trigger:'blur'}]}}},created(){this.load()},methods:{async load(){this.loading=true;try{const r=await pageItemCategory(this.page.current,this.page.size);this.items=r.data.records||[];this.total=r.data.total||0}finally{this.loading=false}},edit(row){this.form=row?{...row}:{categoryName:'',sortNo:0,status:1};this.open=true;this.$nextTick(()=>this.$refs.form&&this.$refs.form.clearValidate())},save(){this.$refs.form.validate(async valid=>{if(!valid)return;await(this.form.id?updateItemCategory(this.form):saveItemCategory(this.form));this.$message.success('保存成功');this.open=false;this.load()})},async remove(row){await this.$confirm(`确认删除分类“${row.categoryName}”？已被信息使用的分类可能无法删除。`,'删除分类',{type:'warning'});await deleteItemCategory(row.id);this.$message.success('删除成功');this.load()}}}</script>
<style scoped>.category-page{padding:24px}.page-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-head h2{margin:0;color:#263b50}.page-head p{margin:7px 0 0;color:#8998a8}.category-card{overflow:hidden;border:1px solid #e5edf4;border-radius:14px;background:#fff}.category-cell{display:flex;align-items:center;gap:13px}.category-cell span{display:flex;width:40px;height:40px;align-items:center;justify-content:center;border-radius:12px;color:#4779a8;background:#eaf2f9;font-size:19px}.category-cell strong{color:#2c4155}.danger{color:#e35d65}</style>
